-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla relic_sets con el tipo artefacto).
--
-- Conjuntos de artefactos de Genshin Impact: los 63 del juego, con sus efectos,
-- las cinco piezas (nombre, descripcion e icono) y donde se consiguen.
--
-- Fuentes:
--   Yatta (gi.yatta.moe) -> nombres oficiales en espanol e ingles, efectos,
--     rareza, piezas e iconos.
--   Datos del propio juego (AnimeGameData) -> dominio de cada conjunto.
--   Game8 -> dominio de los conjuntos de la 7.0, que aun no estan en los datos.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

insert into public.relic_sets (
  id, game_id, name, name_en, type, rarity, image_url, one_piece, two_piece, four_piece, how_to_get, pieces, version
)
values
  ('gi-artifact-15043', 'genshin-impact', 'Alborada de la Estrella del Alba y la Luna', 'Aubade of Morningstar and Moon', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_4.png', null, 'Maestría Elemental +80 pts.', 'Cuando el portador de este conjunto está en tu equipo pero no en uso, el daño de Reacción Lunar que inflige aumenta en un 20%. Cuando el nivel de presagio lunar del equipo es de, al menos, resplandor ascendente, el daño de Reacción Lunar aumenta en un 40% adicional. Estos efectos se anularán después de que el portador de este conjunto permanezca en el campo de batalla durante 3 s.', 'Dominio de la bendición: Cámara sagrada · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Sueño Esplendoroso para la Luna","descripcion":"Un ornamento floral tallado con esmero por los artesanos de la antigüedad para las estatuas divinas de las lunas celestiales, con el fin de resaltar la belleza y magnificencia de dichas diosas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Luz del Adiós para la Luna","descripcion":"Una pluma estilográfica que utilizaban los sacerdotes de la antigüedad para escribir letanías a las lunas celestiales, y gracias a la cual obtenían una gran inspiración.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_2.png"},{"pieza":"Arenas del Eón","nombre":"Hora Final para la Luna","descripcion":"Un reloj de arena que utilizaban los sabios de la antigüedad para preguntar a las lunas celestiales por la verdad, y con el que grabaron el momento final.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Libación para la Luna","descripcion":"Una copa de vino que utilizaban los devotos de la antigüedad para realizar ofrendas a las lunas celestiales, y que acabó perdiéndose en el último banquete de celebración de este ritual.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona de Plata para la Luna","descripcion":"Una corona de plata que utilizaban los poetas de la antigüedad para ofrecer poemas a las lunas celestiales, y que se quitaban al leer la última palabra de sus versos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15043_3.png"}]'::jsonb, null),
  ('gi-artifact-15006', 'genshin-impact', 'Bruja Carmesí en Llamas', 'Crimson Witch of Flames', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_4.png', null, 'Bono de Daño Pyro +15%.', 'Aumenta el daño causado por Sobrecarga, Quemadura y Crepitar en un 40%, y el de Vaporización y Derretido en un 15%. El uso de una Habilidad Elemental aumenta los efectos del conjunto de 2 piezas en un 50% durante 10 s. Puede acumularse hasta un máximo de 3 veces.', 'Dominio de la bendición: Llamas flagrantes · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor en Llamas de la Bruja","descripcion":"Una flor que fue tocada por una bruja que quería quemar el mundo. La calidez de sus llamas acaricia las manos de aquellos que la intentan tocar.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Ardiente de la Bruja","descripcion":"Una pluma de pájaro tocada por una bruja que quería quemar el mundo. Su combustión constante hace que aumente drásticamente la temperatura a su alrededor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_2.png"},{"pieza":"Arenas del Eón","nombre":"Fin de los Tiempos de la Bruja","descripcion":"Un reloj que llevaba la bruja que quería quemar el mundo. En él fluyen los años de vida que le dedicó al fuego.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Llama del Corazón de la Bruja","descripcion":"Un jarrón de arcilla ardiente legado por una bruja que quería quemar el mundo. Las llamas de este frasco nunca se apagan, igual que el deseo infame de la Bruja.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_1.png"},{"pieza":"Tiara de Logos","nombre":"Sombrero Abrasador de la Bruja","descripcion":"El sombrero que llevaba una bruja que quería quemar el mundo. Las grandes alas del sombrero podían bloquear su campo de visión.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15006_3.png"}]'::jsonb, null),
  ('gi-artifact-15008', 'genshin-impact', 'Caballería Sanguinaria', 'Bloodstained Chivalry', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_4.png', null, 'Daño Físico +25%.', 'Derrotar a un enemigo hace que no consumas Aguante al lanzar un Ataque Cargado, y que el daño de Ataque Cargado aumente en un 50% durante 10 s.', 'Dominio de la bendición: Sala de piedra · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Corazón de Hierro Sanguinario","descripcion":"Una flor seca, oscura, con manchas de sangre y dura como el acero. Es considerada una especie de souvenir.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Oscura Sanguinaria","descripcion":"Pluma pegada a la capa del Caballero. Tras mancharse de sangre repetidamente, la pluma se tiñó de un color oscuro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Caballero Sanguinario","descripcion":"Un reloj que llevaban los caballeros antiguamente. El líquido que medía las horas ya se ha petrificado. Este reloj ha perdido su única funcionalidad, que era la de medir el tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Caballero Sanguinario","descripcion":"El cáliz de metal de un caballero con una obsesión por la sangre. Su color negro oscuro se debe a la sangre requemada que se quedó agarrada por todo el recipiente durante mucho tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de Hierro Sanguinaria","descripcion":"La máscara de hierro que usaba el Caballero Sanguinario para proteger su cara. Ha habido muchas teorías sobre qué aspecto tenía el rostro que se ocultaba tras ella.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15008_3.png"}]'::jsonb, null),
  ('gi-artifact-15021', 'genshin-impact', 'Cáscara de Sueños Opulentos', 'Husk of Opulent Dreams', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_4.png', null, 'DEF +30%.', 'El personaje que equipe este conjunto de artefactos obtendrá el efecto de “curiosidad” en las siguientes circunstancias: al golpear a un enemigo con un ataque Geo, obtiene una carga, lo cual solo puede ocurrir una vez cada 0.3 s; mientras está en tu equipo pero no en uso, obtiene una carga cada 3 s. Este efecto puede acumularse hasta 4 veces, y cada carga aumenta en un 6% la DEF y otorga un 6% de Bono de Daño Geo. Si el personaje no obtiene una carga de curiosidad en 6 s, perderá una acumulación.', 'Dominio de la bendición: Necrópolis · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Era del Esplendor","descripcion":"Un accesorio dorado con forma de flor de seis pétalos. Su belleza inmarcesible nos recuerda lo efímera que puede ser la prosperidad del mundo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Opulencia","descripcion":"Un objeto con forma de pluma de flecha procedente de una sala aislada. Por compasión de su creadora, este objeto fue abandonado en esa sala junto a un cuerpo dormido.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_2.png"},{"pieza":"Arenas del Eón","nombre":"Canto de la Vida","descripcion":"En Inazuma, estos pequeños objetos son de importación. Ya no tiene el mecanismo que lo hacía funcionar, y sus agujas ya no se mueven.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Calabaza del Despertar","descripcion":"Una calabaza adornada con un color oscuro y polvos dorados. Aunque ya no se distingue su color original, es posible que fuera usada como atrezo para espectáculos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_1.png"},{"pieza":"Tiara de Logos","nombre":"Sombrero del Trotamundos","descripcion":"Un gorro de bambú usado por el trotamundos para protegerse del sol y la lluvia. Al final, se convirtió en un objeto con el que se cubría la cara y ocultaba su expresión.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15021_3.png"}]'::jsonb, null),
  ('gi-artifact-15031', 'genshin-impact', 'Cazador Fantasmal', 'Marechaussee Hunter', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_4.png', null, 'Daño de Ataque Normal y Cargado +15%.', 'Cuando la Vida del personaje aumenta o disminuye, la Prob. CRIT aumenta en un 12%. Este efecto dura 5 s y puede acumularse hasta 3 veces.', 'Dominio de la bendición: Armonía musical · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Broche Floral del Cazador","descripcion":"Una vieja condecoración que en el pasado se otorgaba a las personas que habían hecho heroicas contribuciones en una batalla.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Obertura Maestra","descripcion":"Una herramienta para ajustar los torques de algunos mecanismos antiguos. Ya ha perdido su utilidad práctica.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Veredicto","descripcion":"Un reloj de bolsillo que, en realidad, no mide el tiempo con mucha precisión.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Licorera del Olvido","descripcion":"Un recipiente metálico para alcohol muy fácil de llevar. Se puede meter en el bolsillo de un abrigo para tenerlo a mano.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_1.png"},{"pieza":"Tiara de Logos","nombre":"Semblante del Veterano","descripcion":"Una vieja máscara que sirve para ocultar hasta cierto punto las heridas de la cara. Hay distintos diseños dependiendo del tamaño de la herida y del género de quien la lleve.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15031_3.png"}]'::jsonb, null),
  ('gi-artifact-15038', 'genshin-impact', 'Códice de Obsidiana', 'Obsidian Codex', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_4.png', null, 'Cuando el portador de este conjunto está en uso y en el estado de bendición noctámbula, el daño que inflige aumenta en un 15%.', 'Cuando el portador de este conjunto consume 1 pt. de noctambulismo mientras está en uso, su Prob. CRIT aumenta en un 40% durante 6 s. Este efecto solo se puede activar una vez cada 1 s.', 'Dominio de la bendición: Llamas devoradoras · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Anhelo Xenogénico","descripcion":"Una flor creada muy cuidadosamente con un mineral de color negro. Por la noche, emite una luz de lo más misteriosa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Raíz de la Médula Espiritual","descripcion":"Una pluma que imita la forma de las alas de los dragones de la antigüedad. Tal vez haya sido testigo de alguna época histórica ahora olvidada.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_2.png"},{"pieza":"Arenas del Eón","nombre":"Mito del Reino de la Noche","descripcion":"Un artilugio que no es ni un reloj ni una brújula. En la actualidad, nadie sabe cuál es su uso.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Tentempié de la Disputa","descripcion":"Parece como si alguien hubiera retorcido una piedra y la hubiera golpeado hasta darle esta forma. Pero ¿quién podría tener tanta fuerza?","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona de los Santos","descripcion":"Una corona hecha de obsidiana que se usaba en las coronaciones de los líderes tribales de la antigüedad.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15038_3.png"}]'::jsonb, null),
  ('gi-artifact-15032', 'genshin-impact', 'Compañía Dorada', 'Golden Troupe', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_4.png', null, 'Daño de Habilidad Elemental +20%.', 'Aumenta en un 25% el daño infligido con la Habilidad Elemental. Además, cuando el personaje está en tu equipo pero no en uso, el daño de dicha habilidad aumenta en un 25% adicional. Este efecto se anula 2 s después de entrar en el campo de batalla.', 'Dominio de la bendición: Armonía musical · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Variación de la Serenata Dorada","descripcion":"Una flor orgullosamente abierta y fabricada con almejas, madreperlas y pan de oro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Ave Dorada","descripcion":"Una pluma de ave hecha de una filigrana de oro y plata. En ella hay incrustado un radiante zafiro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_2.png"},{"pieza":"Arenas del Eón","nombre":"Preludio de la Era Dorada","descripcion":"Un elegante reloj de sol hecho con incrustaciones de oro y plata. Para su disco, el tiempo dejó de transcurrir hace mucho.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Clamor de la Noche Dorada","descripcion":"Una antigua ánfora de plata que en el pasado contenía vino de color rubí. Ahora, en cambio, en ella solo queda la salada agua del mar.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_1.png"},{"pieza":"Tiara de Logos","nombre":"Condecoración de la Compañía Dorada","descripcion":"Una corona muy antigua. Más que una pieza para algún monarca, es un objeto de atrezo para una actuación.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15032_3.png"}]'::jsonb, null),
  ('gi-artifact-15016', 'genshin-impact', 'Corazón de las Profundidades', 'Heart of Depth', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_4.png', null, 'Bono de Daño Hydro +15%.', 'Tras usar la Habilidad Elemental, aumenta el daño de Ataque Normal y Ataque Cargado en un 30% durante 15 s.', 'Dominio de la bendición: Helada letal · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Broche Dorado","descripcion":"Un broche cuyo color y brillo se han atenuado. Su revestimiento dorado original se ha perdido debido a la erosión de la brisa marina.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Brisa de los Recuerdos","descripcion":"Una pluma arrastrada por el sollozo de la brisa marina y las sangrientas olas del océano. Su forma y color han ido cambiando con el tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_2.png"},{"pieza":"Arenas del Eón","nombre":"Brújula de Cobre Resistente","descripcion":"Una brújula hecha de cobre cuya manecilla siempre apunta a una costa muy lejana y a un puerto cuya existencia no se conoce.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz de las Profundidades","descripcion":"Un cáliz desteñido que alguien sacó del agua por casualidad. Sus tenues colores murmuran historias que tuvieron lugar bajo las olas del mar.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_1.png"},{"pieza":"Tiara de Logos","nombre":"Gorro de Capitán Manchado de Vino","descripcion":"Un antiguo gorro de capitán con un hedor a alcohol imposible de quitar. En él, hay algunas manchas de vino.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15016_3.png"}]'::jsonb, null),
  ('gi-artifact-15048', 'genshin-impact', 'Corazón Forjado', 'Heart of the Furnace', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_4.png', null, 'ATQ +18%.', 'Durante 12 s después de que el portador de este conjunto de artefactos cause una reacción de Destello Estelar o inflija daño de Destello Estelar, su ATQ aumentará en un 12% y el daño de Destello Estelar de todos los personajes cercanos del equipo aumentará en un 50%. Este efecto se puede activar incluso cuando el portador está en tu equipo pero no en uso. Los bonos de daño otorgados por este conjunto de artefactos no se pueden acumular con los de otro conjunto del mismo tipo.', 'Dominio «Inverted Glacier» (Snezhnaya, versión 7.0) · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Conjetura del Forjador","descripcion":"Él sabía que los vaivenes del corazón humano no son como la temperatura de la forja, cuyos cambios pueden medirse con precisión.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Observación del Forjador","descripcion":"Él sabía que el devenir del mundo no es como el color de la forja, cuyo resultado se puede saber con solo pura observación.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_2.png"},{"pieza":"Arenas del Eón","nombre":"Cálculo del Forjador","descripcion":"Él sabía que el funcionamiento del poder no es como la energía de la forja, cuyo flujo puede controlarse con un simple interruptor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Magnanimidad del Forjador","descripcion":"Él sabía que la fugacidad de la amistad no es como el fuego de una forja, pues este no dejará de arder mientras se le suministre combustible.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_1.png"},{"pieza":"Tiara de Logos","nombre":"Legado del Forjador","descripcion":"Él sabía que la firmeza de los sueños no es como la luz de la forja, la cual puede pasarse como una antorcha a un sucesor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15048_3.png"}]'::jsonb, null),
  ('gi-artifact-15045', 'genshin-impact', 'Dádiva Celestial', 'Celestial Gift', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_4.png', null, 'Recarga de Energía +20%.', 'Si el portador de este conjunto de artefactos ya ha completado la misión de «Lecciones del Aquelarre», tras usar su Habilidad Elemental, obtendrá el efecto de “guía de la luz celestial”, el cual otorga durante 20 s a todos los personajes cercanos del equipo un 20% de bono de daño del elemento correspondiente al elemento del portador. Este efecto se puede activar incluso cuando el portador de este conjunto está en tu equipo pero no en uso. Los bonos de daño otorgados por este conjunto de artefactos no se pueden acumular con los de otro conjunto del mismo tipo.
·Si el equipo tiene el efecto de “taumaturgia: rito secreto”, mejora el efecto de guía de la luz celestial a “himno del mundo terrenal”, de manera que, además del bono correspondiente al tipo elemental del portador, todos los personajes cercanos del equipo también obtendrán un bono de daño correspondiente al elemento de tu personaje en uso del equipo, y ambos Bonos de Daño Elemental pasarán a ser del 40%. Los bonos de daño del mismo tipo elemental no se pueden acumular.', 'Dominio de la bendición: Festín floral · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Fragancia Celestial","descripcion":"Una flor inmarcesible que los cielos le otorgaron a la emisaria. Una vida sin fin dio paso a la codicia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Perdición Celestial","descripcion":"Una pluma del más allá que los cielos le otorgaron a la emisaria. Todos los pecados serán perdonados cuando el destino llegue a su fin.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_2.png"},{"pieza":"Arenas del Eón","nombre":"Decreto Celestial","descripcion":"Un reloj que cuenta el tiempo en sentido contrario, y que los cielos le otorgaron a la emisaria. La prohibición de transgredir se convirtió en el caldo de cultivo de la ira.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Bendición Celestial","descripcion":"Un dulce néctar que los cielos le otorgaron a la emisaria. Un banquete interminable abrió las puertas del deseo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Celestial","descripcion":"Una espléndida corona que los cielos le otorgaron a la emisaria. El poder sin restricciones alimentó su arrogancia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15045_3.png"}]'::jsonb, null),
  ('gi-artifact-15023', 'genshin-impact', 'Deceso del Cinabrio', 'Vermillion Hereafter', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_4.png', null, 'ATQ +18%.', 'Al usar la Habilidad Definitiva, obtienes el efecto de “destello emergente” durante 16 s, el cual aumenta el ATQ en un 8% y, además, hace que cada vez que el personaje pierda Vida, su ATQ aumente en un 10% adicional. Este efecto solo puede aumentar el ATQ un máximo de 4 veces de esta manera y activarse una vez cada 0.8 s. Los efectos de destello emergente se disiparán si el personaje es retirado de combate. Si el personaje vuelve a usar la Habilidad Definitiva mientras dicho efecto está activo, el destello emergente original también se disipará.', 'Dominio de la bendición: Guarida mecánica · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor de la Vitalidad","descripcion":"Un objeto conmemorativo tan vivo como el ser que lo resguardó cientos de años atrás.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Resplandor","descripcion":"Una pluma de brillo tenue en la que se concentran muchos recuerdos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_2.png"},{"pieza":"Arenas del Eón","nombre":"Reliquia Solar","descripcion":"Un antiguo reloj de aspecto robusto y brillante como la arena cristalizada.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Grabación del Contrato","descripcion":"Una antigua copa de arena cristalizada cuyo brillo no se ha perdido con la erosión del tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara Atronadora","descripcion":"Una máscara que, se dice, los habitantes de las montañas crearon para un Yaksha. Pese a su sencillo aspecto, su exterior es realmente lustroso.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15023_3.png"}]'::jsonb, null),
  ('gi-artifact-15046', 'genshin-impact', 'Desilusión Congelada en las Sombras', 'Disenchantment in Deep Shadow', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_4.png', null, 'ATQ +18%.', 'El daño infligido por la reacción de Superconductor aumenta en un 80%, y el de la reacción de Superconductor Estelar aumenta en un 40%. Cuando el portador de este conjunto de artefactos ataca a un enemigo afectado por Superconductor o Superconductor Estelar, la Prob. CRIT de dicho ataque aumenta en un 16%.', 'Dominio de la bendición: Festín floral · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Satén Detenido en la Gloria","descripcion":"El lazo con forma de flor que ella recibió como regalo de una amiga cuyas manos eran gélidas como el hielo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Detenida en la Creación","descripcion":"La pluma que ella otorgó a su seguidor, y con la cual una vez escribió sueños absurdos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_2.png"},{"pieza":"Arenas del Eón","nombre":"Hora Detenida en el Despertar de un Gran Sueño","descripcion":"El reloj que ella le obsequió al taciturno alquimista para recordarle todos sus compromisos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Celebración Detenida en el Clamor","descripcion":"La copa de vino que ella obtuvo de su compañero como parte de la celebración.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_1.png"},{"pieza":"Tiara de Logos","nombre":"Péndulos Detenidos en la Oscilación","descripcion":"El adorno que ella recibió de su único amo como premio.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15046_3.png"}]'::jsonb, null),
  ('gi-artifact-15044', 'genshin-impact', 'Día de los Vientos Alzantes', 'A Day Carved From Rising Winds', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_4.png', null, 'ATQ +18%.', 'Tras golpear a un enemigo con un Ataque Normal o Cargado o con la Habilidad Elemental o Definitiva, se obtiene el efecto de “bendición del viento y la poesía” durante 6 s, el cual aumenta el ATQ en un 25%. Si el portador de este conjunto ya ha completado la misión de «Lecciones del Aquelarre», dicho efecto mejorará y se convertirá en “determinación del viento y la poesía”, el cual aumenta adicionalmente en un 20% la Prob. CRIT del portador que haya superado dicha prueba. Este efecto se puede activar incluso cuando el portador está en tu equipo pero no en uso.', 'Dominio de la bendición: Cámara sagrada · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Canto de la Flor de Viento","descripcion":"Una flor de cristal azulada e inmarcesible que, según dicen, perteneció a una joven exiliada de un pasado muy remoto que rezaba a los mil vientos y a las flores.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Juramento de la Luz del Alba","descripcion":"Una pluma de color claro y puro como la luz del alba que, según dicen, perteneció a una guardia real de un pasado muy remoto que renunció a su nombre.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_2.png"},{"pieza":"Arenas del Eón","nombre":"Nota de la Melodía Primaveral","descripcion":"Un reloj de arena que contiene unos finos granos azulados. Por alguna razón, por más que se voltee, la arena nunca cae.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Historia sin Contar del Heldenepos","descripcion":"Una copa de vino de color azulado y estilo antiguo que, según dicen, perteneció a un bardo anónimo de un pasado muy remoto.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_1.png"},{"pieza":"Tiara de Logos","nombre":"Minnesang Melancólico de Amor","descripcion":"Un lujoso accesorio de cabeza adornado con jade y cristal que, según dicen, era un amuleto que el Rey de la Tempestad otorgó en un pasado muy remoto a la persona que más le importaba.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15044_3.png"}]'::jsonb, null),
  ('gi-artifact-14002', 'genshin-impact', 'Domador de Truenos', 'Thundersoother', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_4.png', null, 'RES Electro +40%', 'Aumenta el Daño contra los enemigos afectados por Electro un 35%.', 'Dominio de la bendición: Fuego purificador · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Corazón del Domador de Truenos","descripcion":"Una flor que solo crece en zonas tormentosas. Da el coraje necesario para salir al exterior en días de tormenta extrema.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Domador de Truenos","descripcion":"Las leyendas dicen que el emblema del héroe que domó los truenos era una pluma de pájaro que flotaba a través de tormentas eléctricas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_2.png"},{"pieza":"Arenas del Eón","nombre":"Tiempo del Domador de Truenos","descripcion":"Un reloj que manejaba el guerrero que controlaba los truenos y los relámpagos. Los cristales rotos del reloj desaparecieron con el paso del tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Domador de Truenos","descripcion":"El cáliz de vino del Domador de Truenos. Se dice que el héroe que amansó a la bestia del trueno bebió rayos púrpuras de este cáliz.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona del Domador de Truenos","descripcion":"La corona que recibió el ancestral Domador de Truenos tras derrotar a la Bestia del Trueno que amenazaba su territorio.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14002_3.png"}]'::jsonb, null),
  ('gi-artifact-14004', 'genshin-impact', 'Doncella Amada', 'Maiden Beloved', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_4.png', null, 'Aumenta en un 15% la curación realizada.', 'El uso de una Habilidad Elemental o Definitiva aumenta en un 20% la curación recibida de todos los miembros del equipo durante 10 s.', 'Dominio de la bendición: Danza del acero · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Corazón Distante de la Doncella","descripcion":"Una delicada y orgullosa flor que nunca se ha marchitado. Sigue emitiendo una fragancia irresistible.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Recuerdos de la Doncella","descripcion":"Plumas decorativas cuya finalidad era la de recordar a alguien. Vuelan como aves migratorias siguiendo al viento.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_2.png"},{"pieza":"Arenas del Eón","nombre":"Juventud Pasajera de la Doncella","descripcion":"El tiempo no espera a nadie. Ni siquiera a la belleza de la Doncella, que desapareció tras años de admiración por parte de sus pretendientes.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Pasatiempo de la Doncella","descripcion":"No se considera una bebida alcohólica fuerte, sino una especie de té negro. Es más dulce que amargo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_1.png"},{"pieza":"Tiara de Logos","nombre":"Belleza Desvanecida de la Doncella","descripcion":"Un sombrero de mujer bien cuidado. Puede ocultar el rostro de la persona que lo lleva si no quiere mostrarlo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14004_3.png"}]'::jsonb, null),
  ('gi-artifact-15024', 'genshin-impact', 'Eco del Sacrificio', 'Echoes of an Offering', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_4.png', null, 'ATQ +18%.', 'Al golpear a un enemigo con un Ataque Normal, hay una probabilidad del 36% de activar el efecto de “ritual del valle”, el cual aumenta el daño de Ataque Normal en una cantidad equivalente al 70% del ATQ. Este efecto se anula 0.05 s después de infligir daño con un Ataque Normal. Si dicho ataque no activa ritual del valle, la probabilidad de activarlo con el siguiente golpe de Ataque Normal aumenta en un 20%. Esta activación solo puede ocurrir una vez cada 0.2 s.', 'Dominio de la bendición: Guarida mecánica · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Aromaespíritu","descripcion":"Una figura de jade con forma de flor. Cierta fragancia fantasmal parece rezumar de ella.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Hoja de Jade","descripcion":"Un adorno de jade parecido a una hoja. En el pasado, tenía un significado muy especial para dos determinadas amigas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_2.png"},{"pieza":"Arenas del Eón","nombre":"Símbolo Ceremonial","descripcion":"Un adorno de jade redondo. Según una leyenda, simbolizaba en algún sitio el inicio de un ritual.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Taza de la Fuente","descripcion":"Una taza de té de la que emana un constante flujo de agua cristalina. Es incierto si se trata de un regalo, una reliquia o un objeto perdido de los Adeptus.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_1.png"},{"pieza":"Tiara de Logos","nombre":"Aretes Torrenciales","descripcion":"Unos aretes hechos de un hermoso jade. Tienen un tacto sumamente suave.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15024_3.png"}]'::jsonb, null),
  ('gi-artifact-15020', 'genshin-impact', 'Emblema del Destino', 'Emblem of Severed Fate', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_4.png', null, 'Recarga de Energía +20%.', 'Aumenta el daño infligido con la Habilidad Definitiva en una cantidad equivalente al 25% de la Recarga de Energía. Se puede obtener un aumento del 75% como máximo.', 'Dominio de la bendición: La búsqueda de los arces · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Guardamano del Honor","descripcion":"Cuenta la leyenda que este magnífico guardamano le fue otorgado a la oni que traicionó a la Shogun.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Laceración","descripcion":"Una pluma negra perteneciente a una guerrera tengu y muy apreciada por un gran samurái del pasado.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_2.png"},{"pieza":"Arenas del Eón","nombre":"Inrou de la Tempestad","descripcion":"Una exquisita cajita de laca de color violeta oscuro que sirve para guardar objetos. Está decorada con brillantes incrustaciones de caracolas y oro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz Escarlata","descripcion":"Un exquisito cáliz para guardar vino que perteneció a un reconocido samurái.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_1.png"},{"pieza":"Tiara de Logos","nombre":"Casco Ornamentado","descripcion":"Un casco firme y seguro que un honorable samurái usaba para protegerse.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15020_3.png"}]'::jsonb, null),
  ('gi-artifact-15036', 'genshin-impact', 'Ensoñación Inacabada', 'Unfinished Reverie', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_4.png', null, 'ATQ +18%.', '3 s después de salir de combate, el daño infligido aumenta en un 50%. Si estando en combate han pasado más de 6 s sin que haya ningún enemigo cercano quemado, dicho aumento de daño irá disminuyendo en un 10% por segundo, hasta llegar al 0%. Si hay algún enemigo cercano quemado, el daño infligido aumenta en un 10% por segundo, hasta llegar al 50%. Estos efectos se pueden activar incluso cuando el personaje que lleva equipado este conjunto de artefactos está en tu equipo pero no en uso.', 'Dominio de la bendición: Variación · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Secreta Rutilante","descripcion":"Una flor hecha de roca gris y decorada con pan de oro. Cuenta la leyenda que sirvió para diferenciar entre aliados y enemigos durante una guerra.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Cola Esmeralda Descolorida","descripcion":"Una pluma de cola ornamental cuyos colores ya están muy apagados. Al parecer, los patrones que hay en ella fueron obra de un artesano de la antigüedad.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_2.png"},{"pieza":"Arenas del Eón","nombre":"Momento de Aprehensión","descripcion":"Un reloj de sol de una antigua nación. Tiene unas diminutas marcas que solo se llegan a apreciar si uno se fija muy bien.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Jarra del Gran Plan","descripcion":"Una jarra de cerámica con tres patas. En el pasado, numerosos héroes bebieron vino de ella al lado de hogueras mientras hablaban de sus ambiciones y anhelos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Descoronada","descripcion":"Una corona de oro decorada con turquesas y plumas esmeralda. Nunca la han colocado sobre un cojín de terciopelo ni la han usado en una coronación.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15036_3.png"}]'::jsonb, null),
  ('gi-artifact-15027', 'genshin-impact', 'Épica del Pabellón del Desierto', 'Desert Pavilion Chronicle', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_4.png', null, 'Bono de Daño Anemo +15%.', 'Tras golpear a un enemigo con un Ataque Cargado, la Vel. de Ataque Normal del personaje aumenta en un 10%, y el daño de Ataque Normal, Cargado y Descendente aumenta en un 40% durante 15 s.', 'Dominio de la bendición: Ciudadela del desierto · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Inicios de la Capital de los Reyes","descripcion":"Una flor artificial que emite un espléndido brillo. Si uno acerca su oído, podrá escuchar levemente una bella risa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Fin de los Reinos Dorados","descripcion":"Una reluciente pluma artificial que forma parte del legado de un antiguo reino humano. Parece como si contuviera el gañido de un halcón.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Extravío","descripcion":"Un antiguo reloj en cuyo centro brillan y vibran los fragmentos de una genio. Parece como si estuviera narrando alguna historia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Salvaguardia del Sueño Embriagador","descripcion":"Una antigua y hermosa copa dorada. Aunque no contiene nada, en su interior se escucha el murmullo de un eco.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_1.png"},{"pieza":"Tiara de Logos","nombre":"Legado del Heredero del Desierto","descripcion":"Unos pendientes largos de oro nacarado con incrustaciones de gemas que desprenden un magnífico brillo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15027_3.png"}]'::jsonb, null),
  ('gi-artifact-15001', 'genshin-impact', 'Final del Gladiador', 'Gladiator''s Finale', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png', null, 'ATQ +18%.', 'Aumenta el daño de Ataque Normal en un 35% si el personaje usa una espada ligera, mandoble o lanza.', 'Jefes de mundo y jefes semanales · Recompensas de la Espiral del Abismo · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Nostalgia del Gladiador","descripcion":"Nadie sabe por qué el legendario y sanguinario Gladiador siempre llevaba esta flor en el pecho, que era su único punto débil.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Destino del Gladiador","descripcion":"Una pluma que sueña con tener la libertad de un halcón. Al final de la legendaria carrera del Gladiador, el pájaro indomable puso esta pluma en su corazón.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_2.png"},{"pieza":"Arenas del Eón","nombre":"Esperanza del Gladiador","descripcion":"Un reloj que atestigua los días sangrientos del Gladiador en el coliseo. Para él, contaba los días que le quedaban para ser libre.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Embriaguez del Gladiador","descripcion":"La copa de oro usada por un antiguo gladiador para beber el vino de la victoria. En ella, se acumulan infinitos recuerdos memorables.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_1.png"},{"pieza":"Tiara de Logos","nombre":"Triunfo del Gladiador","descripcion":"Un casco que una vez perteneció a un gladiador. Manchado con la sangre de incontables enemigos, es apreciado por mucha gente.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_3.png"}]'::jsonb, null),
  ('gi-artifact-15028', 'genshin-impact', 'Flor Olvidada del Paraíso', 'Flower of Paradise Lost', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_4.png', null, 'Maestría Elemental +80 pts.', 'Aumenta en un 40% el daño que inflige el portador de este conjunto con las reacciones de Florecimiento, Sobreflorecimiento y Crepitar, y en un 10% el daño que inflige con la reacción de Florecimiento Lunar. Además, cuando el portador de este conjunto causa alguna de estas reacciones, el bono anterior aumenta en un 25%. Este efecto dura 10 s, puede acumularse hasta 4 veces y ocurrir una vez por segundo. Puede activarse incluso cuando el portador del conjunto está en tu equipo pero no en uso.', 'Dominio de la bendición: Ciudadela del desierto · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Esplendor de la Dama Luna","descripcion":"Una flor tallada exquisitamente a partir de amatista. Su forma emula la de una flor de la antigüedad que ya está casi extinta.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Festín del Marchitamiento","descripcion":"La pluma de un ave que se extinguió hace ya mucho tiempo. Los antiguos creyentes de la Diosa de las Flores le añadieron unas radiantes y hermosas incrustaciones de oro y gemas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_2.png"},{"pieza":"Arenas del Eón","nombre":"Tiempo Estancado","descripcion":"Un reloj de arena cuyos granos ya no se mueven. Por más que se gire, no responde al paso del tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Frasco Mágico de la Confidencia","descripcion":"Un pequeño frasco de cristal púrpura cerrado herméticamente con un tapón de esmeralda.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona de Amatista","descripcion":"Una corona con incrustaciones de amatista y esmeralda. Podría tratarse de un accesorio para la cabeza que llevaban los antiguos sacerdotes de la Diosa de las Flores.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15028_3.png"}]'::jsonb, null),
  ('gi-artifact-15035', 'genshin-impact', 'Fragmento de la Armonía Fantasiosa', 'Fragment of Harmonic Whimsy', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_4.png', null, 'ATQ +18%.', 'Cuando el valor de un pacto vital aumenta o disminuye, el daño que inflige el personaje aumenta en un 18%. Este efecto dura 6 s y puede acumularse hasta 3 veces.', 'Dominio de la bendición: Variación · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Preludio de la Sinfonía Armónica","descripcion":"Una flor plenamente abierta con decoraciones de oro y basalto azul. Antiguamente, era una medalla de honor otorgada a los humanos inmortales.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Nocturno del Mar de Antaño","descripcion":"Una pluma ornamental hecha a semejanza de las alas de la legendaria abeja dorada. Hasta la brisa más suave la hace zarandearse.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_2.png"},{"pieza":"Arenas del Eón","nombre":"Gran Burla del Giro del Destino","descripcion":"Un reloj que emula la rueda del destino. En la actualidad, no tiene forma de girar.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Rapsodia del Icor Derramado","descripcion":"Un ritón con base de cobre hecho en un horno que, en el pasado, estaba lleno del vino del paraíso.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_1.png"},{"pieza":"Tiara de Logos","nombre":"Vals Fantasioso de la Ruina","descripcion":"Una máscara cubierta con pan de oro. Podría tratarse de una reliquia perteneciente al comandante de alguna legión.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15035_3.png"}]'::jsonb, null),
  ('gi-artifact-15030', 'genshin-impact', 'Fulgor de Vurukasha', 'Vourukasha''s Glow', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_4.png', null, 'Vida +20%.', 'El daño de la Habilidad Elemental y Definitiva aumenta en un 10%. Cuando el portador de este artefacto recibe daño, el incremento de daño anteriormente mencionado aumenta en un 80% durante 5 s. Este efecto puede acumularse hasta 5 veces, cada acumulación se calcula de manera independiente y se puede activar incluso cuando el portador está en tu equipo pero no en uso.', 'Dominio de la bendición: Fortaleza señera · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Estambre Primordial de la Jvarena","descripcion":"Una insignia que solían llevar los peregrinos de otros tiempos. Tiene la apariencia de una bella flor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Cromática","descripcion":"Una pluma decorativa elaborada con la máxima sofisticación. Irradia el lustre característico de unas hojas verdes y unas flores fragantes.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_2.png"},{"pieza":"Arenas del Eón","nombre":"Marchitamiento de Antaño","descripcion":"Un reloj antiguo que irradia energía jvarena. Contiene un líquido de gran pureza que parece tener vida propia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Festín del Júbilo Inconmensurable","descripcion":"Una hermosa copa, ahora completamente vacía, que antaño contenía el néctar más exquisito.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_1.png"},{"pieza":"Tiara de Logos","nombre":"Corazón Refulgente de la Jvarena","descripcion":"Unos aretes elegantes y coloridos. Su fulgor desprende el brillo de cien flores.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15030_3.png"}]'::jsonb, null),
  ('gi-artifact-15005', 'genshin-impact', 'Furia del Trueno', 'Thundering Fury', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_4.png', null, 'Bono de Daño Electro +15%.', 'Aumenta en un 40% el daño infligido por Sobrecarga, Electrocargado, Superconductor y Sobreflorecimiento, y además, tanto el bono de daño generado por Intensificación como el daño infligido por las reacciones de Electrocargado Lunar y Superconductor Estelar aumentan en un 20%. Al causar una de estas reacciones o una reacción de Aceleración, el TdE de la Habilidad Elemental se reduce en 1 s. Este efecto solo puede ocurrir una vez cada 0.8 s.', 'Dominio de la bendición: Fuego purificador · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Misericordia del Ave del Trueno","descripcion":"Una flor del trueno que sobrevivió al furioso pisoteo y a las llamas abrasadoras de una catástrofe destructiva del pasado.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Superviviente de la Catástrofe","descripcion":"Una pluma eléctrica dejada por el Ave del Trueno como venganza. Aun hoy en día sigue lanzando rayos y truenos llenos de furia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Arena del Trueno","descripcion":"El reloj de arena utilizado por la tribu que adoraba al Ave del Trueno para predecir su llegada. Cuando la tribu dejó de existir, el reloj cayó en el olvido.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Presagio de la Tormenta","descripcion":"Un cáliz que contiene la sangre de gente inocente usada en rituales sagrados. El sonido del trueno que retumba en su interior expresa una furia desbordante.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona del Invocador de Truenos","descripcion":"Una corona usada en la antigüedad por los chamanes que adoraban al Ave del Trueno. Por desgracia, ni siquiera la fe más devota podía impresionar a la violenta bestia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15005_3.png"}]'::jsonb, null),
  ('gi-artifact-15039', 'genshin-impact', 'Juramento de la Noche', 'Long Night''s Oath', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_4.png', null, 'Aumenta en un 25% el daño del Ataque Descendente.', 'Cuando el portador de este conjunto golpea a un enemigo con un Ataque Descendente/Ataque Cargado/Habilidad Elemental, obtiene 1/2/2 cargas de “resplandor eterno”. Los Ataques Descendentes, Ataques Cargados o Habilidades Elementales pueden activar este efecto una vez por segundo de forma independiente. Resplandor eterno: el daño de los Ataques Descendentes aumenta en un 15% durante 6 s. Este efecto puede acumularse hasta 5 veces y la duración de cada acumulación se calcula de manera independiente.', 'Dominio de la bendición: Creación de las llamas · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Juramento del Lamparero","descripcion":"Una flor de metal que solían llevar los soldados ratnik y que simboliza el solemne juramento de vigilancia eterna que hizo su dueño original.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Ruiseñor","descripcion":"Un accesorio para sombrero fabricado cuidadosamente con plumas de ruiseñor. Se dice que su forma fue definida por el primer Forjador de Lámparas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_2.png"},{"pieza":"Arenas del Eón","nombre":"Campana Fúnebre del Inmortal","descripcion":"Una campana de bronce que llevaba un guerrero que se adentró en un abismo. Su lamento resuena a menudo en la oscuridad de la noche.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cuerno Insonoro","descripcion":"Un cuerno que en el pasado se utilizaba para convocar a los devotos de un juramento. Hace tiempo que perdió su utilidad.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_1.png"},{"pieza":"Tiara de Logos","nombre":"Morrión Contaminado","descripcion":"Un antiguo y pesado casco que simboliza el legado de un antiguo linaje de guerreros del norte.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15039_3.png"}]'::jsonb, null),
  ('gi-artifact-15018', 'genshin-impact', 'Llamas Albinas', 'Pale Flame', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_4.png', null, 'Daño Físico +25%.', 'Al atacar a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 9% durante 7 s. Este efecto puede acumularse hasta 2 veces y activarse cada 0.3 s. Al alcanzar 2 acumulaciones, el efecto de dos piezas del conjunto aumenta en un 100%.', 'Dominio de la bendición: Perseverancia · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Inmaculada","descripcion":"Una flor azul, dura y artificial. Sus pétalos nunca se marchitarán y su color nunca se apagará.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Doctor Sabio","descripcion":"Una pluma de mal agüero con un borde muy afilado. Quizás representa una naturaleza sin ningún tipo de inhibiciones.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_2.png"},{"pieza":"Arenas del Eón","nombre":"Momento de Cese","descripcion":"Un reloj de bolsillo cuya tapa no se puede abrir. No obstante, se puede oír el sonido de sus manecillas marcando el paso inexorable del tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz de la Trascendencia","descripcion":"Un cáliz con un diseño muy intrincado. Por su apariencia, es imposible saber de qué época procede.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de la Burla","descripcion":"Una máscara que cubre la cara y oculta a los demás la expresión facial.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15018_3.png"}]'::jsonb, null),
  ('gi-artifact-15034', 'genshin-impact', 'Murmullo del Bosque Reverberante', 'Nighttime Whispers in the Echoing Woods', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_4.png', null, 'ATQ +18%.', 'Tras usar la Habilidad Elemental, el personaje obtiene un 20% de Bono de Daño Geo durante 10 s. Si está protegido por un escudo creado mediante la reacción de Cristalización o si en las cercanías hay algún pilar lunar creado con la reacción de Cristalización Lunar, dicho efecto aumenta en un 150%. Este aumento adicional se eliminará en 1 s si no se cumplen las condiciones anteriores.', 'Dominio de la bendición: Congregación de la decadencia · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Ornamental de la Abnegación","descripcion":"El broche que solía llevar la bruja de cierta historia. Presenta un ornamento con forma de mariposa, al igual que los demás accesorios por los que sentía predilección.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Sinceridad","descripcion":"La pluma que utilizaba la bruja de cierta historia. Posee unas cualidades tan extraordinarias que ni siquiera vale la pena mencionar la fluidez y suavidad con la que escribe.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Arena de la Fidelidad","descripcion":"El reloj de arena del que dependía la bruja de cierta historia. Cuenta la leyenda que, si le recitas un encantamiento equivocado, el tiempo empezará a transcurrir más rápido de lo normal.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Tintero de la Magnanimidad","descripcion":"El tintero que utilizaba la bruja de cierta historia. Posee un encantamiento de un poder comparable al de la pluma que se mojaba en él.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_1.png"},{"pieza":"Tiara de Logos","nombre":"Sombrero del Afecto","descripcion":"El sombrero favorito de la bruja de cierta historia. La elegancia y, al mismo tiempo, informalidad de este accesorio eran las dos cosas que más le gustaban de él.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15034_3.png"}]'::jsonb, null),
  ('gi-artifact-15041', 'genshin-impact', 'Noche de la Revelación del Cielo', 'Night of the Sky''s Unveiling', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_4.png', null, 'Maestría Elemental +80 pts.', 'Cuando un personaje cercano del equipo causa una Reacción Lunar, si el portador de este conjunto está en uso, obtiene durante 4 s el efecto de “luna refulgente: cavilación”, de manera que, cuando el presagio lunar del equipo es resplandor naciente/resplandor ascendente, la Prob. CRIT aumenta en un 15/30% respectivamente. Por cada efecto de luna refulgente diferente que tengan los personajes, el daño de las Reacciones Lunares de todos los miembros del equipo aumentará en un 10%. Los efectos producidos por luna refulgente no se pueden acumular.', 'Dominio de la bendición: Derivación de las profundidades · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Anhelaverdad","descripcion":"Una reliquia tallada en forma de flor. Parece simbolizar una existencia aterradora que se despliega como si de pétalos se tratase.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Pecado","descripcion":"Una pluma de color oscuro que servía para decorar sombreros de fieltro. Desentona bastante con los gustos estéticos de la aristocracia de Snezhnaya.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Mandato","descripcion":"Un sofisticado reloj de sonería que funciona gracias a un poder misterioso, pero que no parece servir para indicar la hora.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz Rebosante","descripcion":"Un cáliz especial que se utilizaba en los banquetes de la corte. En el pasado se empleaba para realizar cierta clase de magia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Aciaga","descripcion":"Una corona hecha a semejanza de la diadema que solía llevar un pecador. Quizá, para algunas personas, el amor y el pecado comparten el mismo origen.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15041_3.png"}]'::jsonb, null),
  ('gi-artifact-14001', 'genshin-impact', 'Nómada del Invierno', 'Blizzard Strayer', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_4.png', null, 'Bono de Daño Cryo +15%.', 'Aumenta en un 20% la Prob. CRIT contra los enemigos afectados por Cryo. Si el enemigo está Congelado, la Prob. CRIT aumentará en un 20% adicional.', 'Dominio de la bendición: Helada letal · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Anhelo de la Ventisca","descripcion":"Una especie de flor, ahora extinta desde hace mucho tiempo, que se obtenía de los glaciares. Incluso el guerrero más arrogante una vez se inclinó ante ella.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Obstinación Perforahielos","descripcion":"Una pluma tan fría como el crudo invierno. Transmite una sensación parecida a la del aleteo de un pájaro que, al volar sobre las llanuras y los picos nevados, levanta un viento gélido.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_2.png"},{"pieza":"Arenas del Eón","nombre":"Retorno a las Tierras del Hielo","descripcion":"El reloj que usaba la gente de la tierra natal del Rompehielo. Lo que hay adentro no es arena, sino un polvo helado que nunca se derrite.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Orgullo del Invierno","descripcion":"Una copa tallada en hielo, tan gélida como el invierno. En el pasado, contenía vino que no se congelaba.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_1.png"},{"pieza":"Tiara de Logos","nombre":"Eco de la Escarcha","descripcion":"Una antigua corona heroica que simboliza el sueño de conquistar la nieve y el hielo. Es un testimonio del coraje necesario para resistir el frío del invierno.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14001_3.png"}]'::jsonb, null),
  ('gi-artifact-15003', 'genshin-impact', 'Orquesta del Errante', 'Wanderer''s Troupe', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png', null, 'Maestría Elemental +80 pts.', 'Aumenta el daño de ATQ Cargado en un 35% si el personaje usa catalizador o arco.', 'Jefes de mundo y jefes semanales · Recompensas de la Espiral del Abismo · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Luz Matinal de la Orquesta","descripcion":"Pequeña insignia en forma de flor. Si prestas atención, podrás escuchar las dulces notas de una flauta y un coro de voces.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Bardo","descripcion":"Una pluma de flecha de color azul que no se ha deteriorado con el paso del tiempo. Parece llevar consigo el sonido melódico de un arpa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Acto Final","descripcion":"Un reloj de arena que se usaba para cronometrar los conciertos de una orquesta. Por desgracia, estos conciertos ya hace tiempo que no se celebran.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cantimplora del Errante","descripcion":"Una antigua jarra con cuerdas musicales en su interior. Al fluir el agua, emite unas melodías maravillosas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_1.png"},{"pieza":"Tiara de Logos","nombre":"Sombrero del Director","descripcion":"A pesar de haber vivido innumerables vicisitudes, sigue siendo un sombrero glamuroso. En su interior resuena una antigua melodía.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_3.png"}]'::jsonb, null),
  ('gi-artifact-15037', 'genshin-impact', 'Pergamino del Héroe de la Ciudad de las Cenizas', 'Scroll of the Hero of Cinder City', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_4.png', null, 'Cuando un personaje cercano del equipo causa una explosión noctámbula, el portador de este conjunto recupera 6 pts. de Energía Elemental.', 'Cuando el portador de este conjunto causa una Reacción Elemental relacionada con su tipo elemental, los Bonos de Daño Elemental relacionados con esa Reacción Elemental de todos los personajes cercanos del equipo aumentan en un 12% durante 15 s. Si el portador de este conjunto está en el estado de bendición noctámbula cuando se activa este efecto, los Bonos de Daño Elemental relacionados con esa Reacción Elemental de dichos personajes aumentan en un 28% adicional durante 20 s. Estos efectos se pueden activar incluso cuando el portador está en tu equipo pero no en uso. Los bonos de daño otorgados por este conjunto de artefactos no se pueden acumular con los de otro conjunto del mismo tipo.', 'Dominio de la bendición: Llamas devoradoras · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Talismán del Domador de Bestias","descripcion":"Una flor creada con sílex y vidriagón que simboliza que su portador ha obtenido el derecho a convertirse en domador de bestias.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Distintivo de los Patrullamontañas","descripcion":"Una insignia que usaban los patrullamontañas para marcar el camino. Al tener forma de pluma, llama mucho la atención si uno se la encuentra.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Sol Dorado de la Mistagoga","descripcion":"Un reloj de sol cuya forma, ciertamente, recuerda a la del sol. Los motivos decorativos que tiene simbolizan el ciclo de la vida y la muerte.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz en Garra del Erudito Itinerante","descripcion":"Un cáliz para beber licor cuya forma es sorprendentemente similar a la garra de un saurio. Seguro que su creador tenía sus motivos para crear semejante objeto.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara Emplumada del Guerrero Maligno","descripcion":"Una máscara emplumada con forma de cabeza de halcón alrededor de la cual giraban múltiples leyendas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15037_3.png"}]'::jsonb, null),
  ('gi-artifact-15022', 'genshin-impact', 'Perla Oceánica', 'Ocean-Hued Clam', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_4.png', null, 'Bono de Curación +15%.', 'Cuando el personaje que equipa este conjunto de artefactos cura a otro, crea el efecto de “burbuja marina” durante 3 s, el cual registra la cantidad de Vida regenerada (incluida la regenerada por encima del 100%). Tras ello, la burbuja marina estalla e inflige contra los enemigos cercanos un daño basado en el 90% de la cantidad regenerada. Este daño se calcula de manera similar al de las reacciones de Electrocargado, Superconductor, etc., pero no varía en función de la Maestría Elemental, el nivel del personaje o el bono de daño de las reacciones. Solo se puede crear una burbuja marina cada 3.5 s, la cual solo puede registrar un máximo de 30 000 pts. de Vida regenerada, incluyendo la regenerada por encima del 100%. Además, solo puede existir una burbuja marina en tu equipo al mismo tiempo. Cuando el personaje que equipa este conjunto de artefactos está en el equipo pero no en uso, también podrá activar este efecto.', 'Dominio de la bendición: Necrópolis · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor Marina","descripcion":"Una flor que se ha teñido de muchos de los colores del océano caprichoso y que reluce con hermosos reflejos bajo la luz de la luna.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Palacio de las Profundidades","descripcion":"Una suave pluma del color del coral. Se dice que proviene del traje ceremonial de una miko.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_2.png"},{"pieza":"Arenas del Eón","nombre":"Cauri de la Despedida","descripcion":"Una concha marina sin ninguna imperfección que proviene de las profundidades del océano.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Jaula de Perlas","descripcion":"Las perlas relucientes que las miko de la Isla Watatsumi utilizan como ofrendas brillan eternamente y su fulgor nunca se apaga.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona de Watatsumi","descripcion":"Una corona antigua e intrincada que solían utilizar las clérigas ahora olvidadas. En la actualidad, es una reliquia conservada con gran cuidado por las gentes de Watatsumi.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15022_3.png"}]'::jsonb, null),
  ('gi-artifact-15014', 'genshin-impact', 'Petra Arcaica', 'Archaic Petra', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_4.png', null, 'Bono de Daño Geo +15%.', 'Al obtener un fragmento creado a través de la reacción de Cristalización o al causar una reacción de Cristalización Lunar, todos los miembros del equipo obtienen durante 10 s un 35% de bono de daño del elemento correspondiente. Solo se puede obtener un tipo de Bono de Daño Elemental a la vez mediante este efecto.', 'Dominio de la bendición: El despertar · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor del Acantilado Agrietado","descripcion":"Una flor que brota en las grietas de las rocas y los minerales. Sus pétalos se mecen con la brisa, tal y como una flor real.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Cordillera Escarpada","descripcion":"Una dura pluma de un gran halcón de montaña. La punta de basalto de la pluma a veces brilla con las gotas del rocío.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Sol de Jade Sempiterno","descripcion":"Un reloj de sol tallado en una sola pieza grande de jade. Está tallado con un patrón que registra silenciosamente el paso del tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Escultor de Montañas","descripcion":"Un recipiente de vino que es tan bello como solemne. Hace mil años, estaba repleto de incrustaciones de jade.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de Basalto Inerte","descripcion":"Una máscara majestuosa tallada en basalto. Las cavidades de sus ojos miran con frialdad hacia adelante.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15014_3.png"}]'::jsonb, null),
  ('gi-artifact-15025', 'genshin-impact', 'Recuerdos del Bosque', 'Deepwood Memories', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_4.png', null, 'Bono de Daño Dendro +15%.', 'Tras golpear a un enemigo con una Habilidad Elemental o Definitiva, la RES Dendro de dicho enemigo se reduce en un 30% durante 8 s. Este efecto se puede activar incluso cuando el personaje que lleva este conjunto equipado está en tu equipo pero no en uso.', 'Dominio de la bendición: Manas-vijñana · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Visitante del Laberinto","descripcion":"Una flor dorada arrancada de la corona del Rey del Bosque.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Sabio de la Espesura","descripcion":"Una hoja de un color esmeralda, ligera como una pluma y extraída de la indumentaria de un sabio del bosque.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_2.png"},{"pieza":"Arenas del Eón","nombre":"Fenecimiento de la Sabiduría","descripcion":"Un reloj utilizado por aquellos que se dedican a la búsqueda de la sabiduría. Lo que contiene no es arena inerte, sino diminutos granos de mostaza.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Lámpara del Exilio","descripcion":"Originalmente era una lámpara de aceite de estilo desértico, pero en algún momento le crecieron unas radiantes hojas verdes.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Láurea","descripcion":"Una corona, obsequio de la soberana divina de las plantas, que fue heredándose entre los distintos reyes del laberinto. Al final, acabó en manos del vasallo de uno de esos reyes.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15025_3.png"}]'::jsonb, null),
  ('gi-artifact-15019', 'genshin-impact', 'Reminiscencia de la Purificación', 'Shimenawa''s Reminiscence', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_4.png', null, 'ATQ +18%.', 'Si el personaje tiene 15 pts. de Energía Elemental o más, perderá 15 pts. al realizar una Habilidad Elemental y el daño infligido con los Ataques Normales, Cargados y Descendentes aumentará en un 50% durante 10 s. Este efecto no puede activarse más de una vez simultáneamente.', 'Dominio de la bendición: La búsqueda de los arces · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor del Entrelazamiento","descripcion":"Un talismán de papel de arroz de exquisita elaboración. Se dice que tiene el poder de hacer los deseos realidad.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Flecha de la Nostalgia","descripcion":"Esta desgastada y vieja flecha mágica parece haber sido guardada con mucho cuidado por alguien.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de la Transitoriedad","descripcion":"Un reloj de bolsillo de bronce decorado con un lazo de papel de arroz y un cascabel. La hora que marca se paró en el alba de un día de otoño.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Corazón de la Esperanza","descripcion":"Un recipiente para guardar palillos de la fortuna. En su fondo hay un mecanismo que hace que la gente saque con mayor probabilidad un palillo de mala fortuna.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de la Mutabilidad","descripcion":"Una máscara ritual de zorro muy bien conservada y con una leve y misteriosa sonrisa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15019_3.png"}]'::jsonb, null),
  ('gi-artifact-15040', 'genshin-impact', 'Réquiem del Corredor', 'Finale of the Deep Galleries', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_4.png', null, 'Bono de Daño Cryo +15%.', 'Cuando el portador de este conjunto tiene 0 pts. de Energía Elemental, tanto el daño de su Ataque Normal como el de su Habilidad Definitiva aumentan en un 60%. Cuando dicho portador inflige daño con su Ataque Normal, el aumento de daño de la Habilidad Definitiva se anulará durante 6 s. Después de que el portador inflija daño con su Habilidad Definitiva, el aumento de daño del Ataque Normal anteriormente mencionado se anulará durante 6 s. Este efecto puede activarse incluso cuando el personaje que lleva este conjunto está en tu equipo pero no en uso.', 'Dominio de la bendición: Creación de las llamas · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Canción Reverberante del Corredor","descripcion":"Una flor de hielo hecha de jade del Reino del Norte. Los pétalos de la flor se han convertido en polvo con el tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Promesa Perdurable del Corredor","descripcion":"Una pluma hecha de jade del Reino del Norte. La luz que refleja no parece pertenecer a este mundo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_2.png"},{"pieza":"Arenas del Eón","nombre":"Momento Olvidado del Corredor","descripcion":"Un reloj de bolsillo elaborado con jade del Reino del Norte. La aguja se detuvo para siempre en el momento de su destrucción.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Gran Banquete del Corredor","descripcion":"Un cáliz hecho de jade del Reino del Norte. Se dice que una antigua civilización lo utilizaba como objeto ceremonial para hacer ofrendas al cielo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Perdida del Corredor","descripcion":"Una máscara nublada por la obsesión, igual que la mente de su antiguo dueño. El jade que contiene parece ser de una época más antigua.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15040_3.png"}]'::jsonb, null),
  ('gi-artifact-15015', 'genshin-impact', 'Retroceso del Meteorito', 'Retracing Bolide', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_4.png', null, 'Protección de Escudo +35%.', 'Los Ataques Normales y Cargados obtienen un 40% de daño adicional mientras estés bajo la protección de un escudo.', 'Dominio de la bendición: El despertar · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor de la Noche de Verano","descripcion":"Una flor artificial en floración eterna. ¿Estará viva?","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Gran Final de la Noche de Verano","descripcion":"Un elegante dardo de madera. Solo se detiene cuando alcanza a su objetivo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de la Noche de Verano","descripcion":"Un reloj de bolsillo que se detuvo en cierto momento.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Globo de Agua de la Noche de Verano","descripcion":"Durante los festivales de verano, no es inusual ver globos llenos de agua. Sin embargo, solo hay uno tan elegante como este.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de la Noche de Verano","descripcion":"Una máscara muy popular hecha a semejanza de una divinidad legendaria.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15015_3.png"}]'::jsonb, null),
  ('gi-artifact-15007', 'genshin-impact', 'Ritual Antiguo de la Nobleza', 'Noblesse Oblige', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_4.png', null, 'Daño de Habilidad Definitiva +20%.', 'Después de lanzar una Habilidad Definitiva, aumenta el ATQ de todos los miembros del equipo en un 20% durante 12 s. Este efecto no puede acumularse.', 'Dominio de la bendición: Sala de piedra · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flora Real","descripcion":"Una flor de seda azul que servía como un distinguido elemento decorativo para llevar en eventos de gala. Su apariencia todavía es igual de fresca que antes de ser abandonada por su dueño.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Real","descripcion":"Una pluma que llevaban en el sombrero los miembros de la nobleza de Mondstadt durante sus cacerías. Todavía permanece intacta después de tanto tiempo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo Real","descripcion":"Un reloj de bolsillo de los aristócratas de Mondstadt. Ha pasado por las manos de innumerables generaciones.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Urna Plateada Real","descripcion":"Antigua urna ornamental que perteneció a una familia noble de Mondstadt. El melancólico viento del tiempo todavía resuena en su interior.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara Real","descripcion":"Una máscara que llevaban los aristócratas en las veladas de fiestas en Mondstadt. Si miras a través de los agujeros de los ojos, podrás ver las grandes celebraciones del pasado.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15007_3.png"}]'::jsonb, null),
  ('gi-artifact-15042', 'genshin-impact', 'Serenata de la Luna Tejida', 'Silken Moon''s Serenade', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_4.png', null, 'Recarga de Energía +20%.', 'Infligir Daño Elemental otorga durante 8 s el efecto de “luna refulgente: veneración”, de manera que, cuando el presagio lunar del equipo es resplandor naciente/resplandor ascendente, la Maestría Elemental de todos los personajes del equipo aumenta en 60/120 pts. respectivamente. Este efecto se puede activar incluso cuando el portador de este conjunto está en tu equipo pero no en uso. Por cada efecto de luna refulgente diferente que tengan los personajes, el daño de las Reacciones Lunares de todos los miembros del equipo aumentará en un 10%. Los efectos producidos por luna refulgente no se pueden acumular.', 'Dominio de la bendición: Derivación de las profundidades · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Lágrima Cristalina de la Errante","descripcion":"Una flor pura e impoluta. Cuenta la leyenda que su belleza se ha mantenido eterna gracias al viento gélido.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma Blanca de la Bendecida","descripcion":"Una pluma pura e impoluta. Dicen que la creó la primera Cantalunas con sus propias manos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_2.png"},{"pieza":"Arenas del Eón","nombre":"Locura Delirante de la Veneraescarcha","descripcion":"Un reloj puro e impoluto que se detuvo junto a los delirios de su antigua dueña.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Gloria Exultante de la Impoluta","descripcion":"Una taza de plata pura e impoluta. Se dice que era un antiguo objeto sagrado que se empleaba en los rituales de los Descendientes Lunaescarcha. Sin embargo, en las ceremonias de la actualidad ya no se usan recipientes como este.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona Sagrada de la Devota","descripcion":"Una corona pura e impoluta cuya forma parece emular las astas de la emisaria espiritual de la arboleda.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15042_3.png"}]'::jsonb, null),
  ('gi-artifact-15002', 'genshin-impact', 'Sombra Verde Esmeralda', 'Viridescent Venerer', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_4.png', null, 'Bono de Daño Anemo +15%.', 'El daño de la reacción de Torbellino aumenta en un 60%, y el de Torbellino Estelar aumenta en un 20%. Dependiendo del tipo elemental del Torbellino, la RES Elemental correspondiente del enemigo se reduce en un 40% durante 10 s. Al causar una reacción de Torbellino Estelar contra un enemigo, su RES Cryo también se reduce en un 40%. Las reducciones del mismo tipo de RES Elemental no se pueden acumular.', 'Dominio de la bendición: Danza del acero · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Recuerdo de Flores Silvestres","descripcion":"En el pasado, esta flor brotaba por todas partes. La Cazadora la usó como broche cuando se marchó de su tierra.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Cazadora Verde Esmeralda","descripcion":"La pluma de una flecha que hace tiempo atravesó a su presa. Sigue estando igual de suave y limpia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_2.png"},{"pieza":"Arenas del Eón","nombre":"Serenidad de la Cazadora Verde Esmeralda","descripcion":"Un increíble dispositivo que solía llevar la Cazadora. Siempre apunta en dirección a su presa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cantimplora de la Cazadora Verde Esmeralda","descripcion":"Una cantimplora para almacenar agua. Su interior es mucho más grande de lo que parece.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_1.png"},{"pieza":"Tiara de Logos","nombre":"Sombrero de la Cazadora Verde Esmeralda","descripcion":"La corona que la Cazadora llevaba con gran orgullo. Es de un color verde como la naturaleza salvaje.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15002_3.png"}]'::jsonb, null),
  ('gi-artifact-15033', 'genshin-impact', 'Son de Antaño', 'Song of Days Past', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_4.png', null, 'Bono de Curación +15%.', 'Cuando el portador de este conjunto realiza una curación, crea el efecto de “añoranza” durante 6 s, el cual registra la cantidad de Vida recuperada (incluyendo el exceso de curación). Al terminar la duración, el efecto de añoranza se convierte en el de “marea de antaño”, de manera que cuando tu personaje en uso golpea a un enemigo con un Ataque Normal, Cargado o Descendente o con su Habilidad Elemental o Definitiva, el daño que inflige dicho personaje aumenta en una cantidad equivalente al 8% de la cantidad de Vida recuperada y registrada por añoranza. El efecto de marea de antaño se elimina tras activarse 5 veces o después de 10 s. Por su parte, el efecto de añoranza solo puede registrar un máximo de 15 000 pts. de Vida recuperada y solo puede existir uno al mismo tiempo, pero puede registrar la Vida recuperada por varios portadores de este conjunto. Este efecto se puede activar incluso cuando el portador está en tu equipo pero no en uso.', 'Dominio de la bendición: Congregación de la decadencia · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Juramento Olvidado de Antaño","descripcion":"Una flor inmarcesible hecha de larimar y plata azulada. Incluso hoy en día se sigue considerando un símbolo de resistencia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Remembranza Fugaz de Antaño","descripcion":"Un accesorio con forma de ala de mariposa fabricado con plata y cristales azulados. Cuentan que, en un pasado muy remoto, simbolizaba la promesa de no separarse nunca.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_2.png"},{"pieza":"Arenas del Eón","nombre":"Tañido de Antaño","descripcion":"Un reloj de arena de forma muy particular y fabricado con lapislázuli y jade ácueo. Su diseño está basado en el campanario de Petricor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Sueño Prometido de Antaño","descripcion":"Un hermoso recipiente cuya forma emula la del legendario cáliz de agua pura. Se dice que puede cumplir los deseos más puros de las personas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_1.png"},{"pieza":"Tiara de Logos","nombre":"Poema Legado de Antaño","descripcion":"Un sombrero que, en el pasado, gozó de gran popularidad entre los compositores de ópera de Fontaine. El diseño de su pluma ornamental está inspirado en los yelmos de los legendarios Caballeros Aguapura.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15033_3.png"}]'::jsonb, null),
  ('gi-artifact-15029', 'genshin-impact', 'Sueño de la Ninfa', 'Nymph''s Dream', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_4.png', null, 'Bono de Daño Hydro +15%.', 'Tras golpear a un enemigo con un Ataque Normal, Cargado o Descendente o una Habilidad Elemental o Definitiva, se genera 1 carga de “reflejo de la ninfa” durante 8 s. Con 1/2/3 o más cargas, el ATQ aumenta en un 7/16/25% y el Bono de Daño Hydro aumenta en un 4/9/15%. Las cargas de reflejo de la ninfa creadas con un Ataque Normal, Cargado o Descendente o con la Habilidad Elemental o Definitiva son independientes entre sí.', 'Dominio de la bendición: Fortaleza señera · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor del Periplo","descripcion":"La historia debe llegar a su fin. Y cuando lo haga, hasta las flores más frescas se marchitarán. Sin embargo, la flor del sueño siempre mantendrá su lozanía y emanará un delicioso aroma.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Brujo Maléfico","descripcion":"Una pluma que originalmente servía como ornamento del sombrero de alguien. Con su oscuro color turquesa, es capaz de atraer incontables miradas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_2.png"},{"pieza":"Arenas del Eón","nombre":"Asiduidad de las Ninfas","descripcion":"Un reloj de bolsillo que dejó de funcionar hace mucho tiempo. Transmite la sensación de haber visto los años pasar tras mucho tiempo girando en vano.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Fiesta del Té de la Valentía","descripcion":"Una sofisticada taza de té. Quizá hubo un tiempo en el que compartió con otros deliciosas tardes de charla y descanso.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_1.png"},{"pieza":"Tiara de Logos","nombre":"Monóculo del Dragón Protervo","descripcion":"Un monóculo de lo más sofisticado. Cuenta una antigua leyenda que a través de él se puede vislumbrar el futuro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15029_3.png"}]'::jsonb, null),
  ('gi-artifact-15026', 'genshin-impact', 'Sueños Áureos', 'Gilded Dreams', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_4.png', null, 'Maestría Elemental +80 pts.', 'Tras causar una Reacción Elemental, el personaje que lleve equipado este conjunto obtiene durante 8 s los siguientes fortalecimientos en función de los tipos elementales de los miembros del equipo: por cada personaje del mismo tipo elemental que el portador de este conjunto, el ATQ aumenta en un 14%; por cada personaje de tipo elemental distinto al portador de este conjunto, la Maestría Elemental aumenta en 50 pts. Cada uno de estos efectos se calcula para un máximo de 3 personajes. Este efecto solo se puede activar una vez cada 8 s, y se activará incluso cuando el personaje que lleva este conjunto equipado esté en tu equipo pero no en uso.', 'Dominio de la bendición: Manas-vijñana · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor de Metal Onírica","descripcion":"Un capullo de flor creado con un metal oscuro. Sus pétalos, que ya nunca más podrán volver a abrirse, rodean un pistilo de color escarlata.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Juzgamiento","descripcion":"Una pluma que en el pasado se usaba para medir el peso del corazón de un criminal, pero que ha perdido su función original.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_2.png"},{"pieza":"Arenas del Eón","nombre":"Tiempos Dorados","descripcion":"Un antiguo reloj de sol de un metal con un brillo oscuro. Parece como si estuviera narrando el pasado del desierto.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Festín Final","descripcion":"Una copa de vino usada en los grandes banquetes de la antigüedad. Ha perdido el magnífico lustre que tenía.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_1.png"},{"pieza":"Tiara de Logos","nombre":"Reminiscencia del Rey del Desierto","descripcion":"Una prenda para la cabeza con incrustaciones de oro que solían llevar los sacerdotes del desierto. Su forma emula y recuerda al legendario rey de los habitantes del desierto.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15026_3.png"}]'::jsonb, null),
  ('gi-artifact-15017', 'genshin-impact', 'Tenacidad de la Geoarmada', 'Tenacity of the Millelith', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_4.png', null, 'Vida +20%.', 'Cuando una Habilidad Elemental golpea a un enemigo, el ATQ de todos los personajes del equipo cercanos aumenta en un 20% y su Protección de Escudo aumenta en un 30% durante 3 s. Este efecto puede tener lugar cada 0.5 s y se activa incluso cuando el personaje que lleva equipado este conjunto de artefactos está en tu equipo pero no en uso.', 'Dominio de la bendición: Perseverancia · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Flor del Honor","descripcion":"Una flor hecha de una fina lámina de oro. Representa la gloria y el honor obtenidos por quien la lleva.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de Guerra Ceremonial","descripcion":"Una pluma de halcón que se utiliza en ceremonias. Muestra al resto del mundo la dignidad y resolución de Liyue.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Sol de Oricalco","descripcion":"Un dispositivo muy sencillo para saber la hora. En época de guerra, era parte del equipamiento de la Geoarmada.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Copa del Juramento","descripcion":"Una copa de oro que la Geoarmada utiliza para prestar juramento. Todavía contiene trazas de aroma a vino.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_1.png"},{"pieza":"Tiara de Logos","nombre":"Yelmo Vetusto del General","descripcion":"Un yelmo espléndido procedente de una época ya pasada. Si limpias el polvo acumulado en su superficie, se verá como nuevo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15017_3.png"}]'::jsonb, null),
  ('gi-artifact-15047', 'genshin-impact', 'Testimonio Escarlata', 'Scarlet Proof', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_4.png', null, 'ATQ +18%.', 'Durante 10 s después de que el portador de este conjunto de artefactos cause una reacción de Torbellino Estelar, su Prob. CRIT aumentará en un 16% y su daño de Torbellino Estelar aumentará en un 40%.', 'Dominio «Inverted Glacier» (Snezhnaya, versión 7.0) · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Agradecimiento por tu Devoción","descripcion":"Un adorno floral de un color rojo intenso. Simboliza una gloria tan ardiente como el fuego.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Gloria a tus Hazañas","descripcion":"Una pluma de escribir de un color rojo intenso. Le fue entregada a la sangre más joven.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_2.png"},{"pieza":"Arenas del Eón","nombre":"Tiempo Concedido a Ti","descripcion":"Un reloj de bolsillo de un color rojo intenso. Registra el tiempo límite de una conversación.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Libación de tu Sangre y tus Lágrimas","descripcion":"Una licorera de un color rojo intenso. Mejor que no sepas qué es lo que solía contener.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_1.png"},{"pieza":"Tiara de Logos","nombre":"Homenaje a tu Fe","descripcion":"Un casco de un color rojo intenso. Ojalá haya protegido a alguien.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15047_3.png"}]'::jsonb, null),
  ('gi-artifact-14003', 'genshin-impact', 'Virtuoso Corredor de Lava', 'Lavawalker', 'artefacto', '4-5★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_4.png', null, 'RES Pyro +40%.', 'Aumenta en un 35% el daño contra los enemigos afectados por Pyro.', 'Dominio de la bendición: Llamas flagrantes · Ofrenda mística: transmutación con artefactos de otros conjuntos', '[{"pieza":"Flor de la Vida","nombre":"Determinación del Corredor de Lava","descripcion":"Una flor que se abrió mientras estaba rodeada de llamas. Según la leyenda, los sabios de la antigüedad la llevaron consigo antes de cruzar el mar de fuego.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Liberación del Corredor de Lava","descripcion":"Una pluma de pájaro bañada en lava. Escuchando de cerca, parece oírse el sonido del aleteo de un pájaro en medio de las llamas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_2.png"},{"pieza":"Arenas del Eón","nombre":"Tormento del Corredor de Lava","descripcion":"Un reloj que contiene una brillante y ardiente arena. A pesar del intenso calor, dicha arena fluye sin dejar ningún rastro de deterioro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Despertar del Corredor de Lava","descripcion":"Cuenta la leyenda que el vidrio de este cáliz puede soportar altas temperaturas. Actualmente, su interior está vacío, pero sigue emitiendo calor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_1.png"},{"pieza":"Tiara de Logos","nombre":"Sabiduría del Corredor de Lava","descripcion":"La corona de la sabiduría bañada en llamas. Una vez brilló vivamente a la luz del fuego.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_14003_3.png"}]'::jsonb, null),
  ('gi-artifact-10006', 'genshin-impact', 'Artista Marcial', 'Martial Artist', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_4.png', null, 'Daño de ATQ Normal y ATQ Cargado +15%.', 'Tras usar la Habilidad Elemental, aumenta el daño de Ataque Normal y Ataque Cargado en un 25% durante 8 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Flor Roja del Artista Marcial","descripcion":"Solo este tipo de flor carmesí podía aliviar el dolor del Artista Marcial.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Artista Marcial","descripcion":"Una pluma de ave común. Los expertos las usan para practicar el control de la fuerza, mientras que los novatos hacen abanicos con ellas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Agua del Artista Marcial","descripcion":"Una herramienta para controlar el tiempo del entrenamiento de resistencia. Es más preciso y fiable que un reloj de arena normal.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Copa de Vino del Artista Marcial","descripcion":"Una copa de vino un tanto exquisita para los rituales antes de entrar en combate.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_1.png"},{"pieza":"Tiara de Logos","nombre":"Bandana del Artista Marcial","descripcion":"Vigor, fuerza y voluntad. Esa es la primera lección como aprendiz de artes marciales. Estas tres palabras están escritas en la bandana para que el discípulo nunca las olvide.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10006_3.png"}]'::jsonb, null),
  ('gi-artifact-10005', 'genshin-impact', 'Berserker', 'Berserker', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png', null, 'Prob. CRIT +12%.', 'Cuando la Vida es inferior al 70%, aumenta la Prob. CRIT en un 24%.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Rosa del Berserker","descripcion":"Una flor delicada teñida de rojo que va ligeramente acorde con la esencia del Berserker.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Berserker","descripcion":"La pluma de color añil de un ave que, según la leyenda, presagiaba la muerte. Una parte de ella se ha teñido de rojo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Berserker","descripcion":"El líquido en su interior fluye sin piedad, recordando al Berserker el tiempo que le quedaba en el campo de batalla y los días que le quedaban en este mundo...","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz de Hueso del Berserker","descripcion":"Una copa hecha de los huesos de una bestia desconocida que fueron obtenidos en una cacería.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_1.png"},{"pieza":"Tiara de Logos","nombre":"Máscara de Batalla del Berserker","descripcion":"Una máscara de hierro que se partió por la mitad en feroces batallas.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_3.png"}]'::jsonb, null),
  ('gi-artifact-10003', 'genshin-impact', 'Corazón del Guardián', 'Defender''s Will', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_4.png', null, 'DEF +30%.', 'Por cada miembro de tu equipo con un tipo elemental distinto, La RES Elemental del personaje que lleve este conjunto aumenta en un 30% contra dicho elemento.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Flor del Guardián","descripcion":"La flor de iris atesorada por el Guardián. Nunca tuvo la oportunidad de entregársela a su amor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Insignia del Guardián","descripcion":"Un broche en forma de pluma, símbolo de “la sed por proteger a otros”.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj del Guardián","descripcion":"Un pequeño dispositivo para mostrar la hora actual. Es la única referencia disponible para consultar la hora en las noches sin luna.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cantimplora del Guardián","descripcion":"Un recipiente metálico. Puede usarse para contener cualquier líquido que ayude a olvidar la soledad mientras se observa detenidamente.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_1.png"},{"pieza":"Tiara de Logos","nombre":"Bandana del Guardián","descripcion":"Un paño índigo teñido del color de la noche. Puede usarse como vendaje en una situación de emergencia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10003_3.png"}]'::jsonb, null),
  ('gi-artifact-10002', 'genshin-impact', 'Corazón del Guerrero', 'Brave Heart', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_4.png', null, 'ATQ +18%.', 'Aumenta el daño en un 30% contra enemigos con más del 50% de Vida.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Medalla del Guerrero","descripcion":"Broche muy sencillo hecho con una flor. Es un recuerdo de la primera gran aventura del Guerrero.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Esperanza del Guerrero","descripcion":"La pluma brillante de la cola de un pájaro cantor. Puede inspirar un poco de valor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_2.png"},{"pieza":"Arenas del Eón","nombre":"Determinación del Guerrero","descripcion":"Un antiguo reloj de arena en miniatura sin ningún uso práctico. Es tan incomprensible como el tiempo en sí mismo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Gran Despedida del Guerrero","descripcion":"Un recipiente tosco de madera. Su interior, ahora vacío, estaba repleto de recuerdos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona del Guerrero","descripcion":"Una corona rudimentaria hecha con plantas. Para algunos, es tan preciada como la corona de un rey.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10002_3.png"}]'::jsonb, null),
  ('gi-artifact-10001', 'genshin-impact', 'Corazón del Viajero', 'Resolution of Sojourner', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_4.png', null, 'ATQ +18%.', 'La Prob. CRIT de los Ataques Cargados aumenta en un 30%.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Corazón de la Amistad","descripcion":"Una flor azul celeste en cuyo tallo anudaron un pequeño lazo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Retorno","descripcion":"Una pluma de flecha azul. Lleva en ella la nostalgia del viajero.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_2.png"},{"pieza":"Arenas del Eón","nombre":"Piedra Atrapaluz","descripcion":"Un reloj de sol que es testigo del cambio de las eras. Registra eternamente y en silencio el flujo de los días.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz Extranjero","descripcion":"Una copa austera de porcelana blanca. Alguna vez estuvo llena de licores hasta desbordar.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_1.png"},{"pieza":"Tiara de Logos","nombre":"Corona del Adiós","descripcion":"Una corona de flores que despide un aroma primaveral.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10001_3.png"}]'::jsonb, null),
  ('gi-artifact-10012', 'genshin-impact', 'Erudita', 'Scholar', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_4.png', null, 'Recarga de Energía +20%.', 'Al obtener partículas u orbes elementales, los miembros del equipo que usen arco o catalizador recuperan 3 pts. adicionales de Energía Elemental. Solo puede suceder una vez cada 3 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Marcapáginas de la Erudita","descripcion":"Una flor seca que se usa como marcapáginas. Ha absorbido el aroma de los libros.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Erudita","descripcion":"La pluma de un pájaro que sirve como herramienta para escribir. La punta lleva mucho tiempo teñida de negro.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de la Erudita","descripcion":"Un pequeño reloj de escritorio. Proporciona la única referencia sobre la hora para los eruditos que están todo el día estudiando.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Tintero de la Erudita","descripcion":"Originalmente un recipiente para agua potable. Se ha teñido de negro después de haber sido utilizado para limpiar pinceles.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_1.png"},{"pieza":"Tiara de Logos","nombre":"Monóculo de la Erudita","descripcion":"Este objeto fue creado para mitigar el daño que la lectura intensiva causa a los ojos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10012_3.png"}]'::jsonb, null),
  ('gi-artifact-10009', 'genshin-impact', 'Exiliado', 'The Exile', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png', null, 'Recarga de Energía +20%.', 'Al usar la Habilidad Definitiva, todos los miembros del equipo (a excepción de tu personaje en uso) recuperan 2 pts. de Energía Elemental cada 2 s durante 6 s. Este efecto no puede acumularse.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Flor del Exiliado","descripcion":"Una flor marchita colgada en la camisa. Debe significar algo si un exiliado insiste en llevarla puesta.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Exiliado","descripcion":"No es un accesorio creado intencionadamente. Simplemente es una pluma de pájaro que quedó atrapada en un árbol mientras volaba por la selva.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo del Exiliado","descripcion":"La esfera del reloj de cristal se ha roto y sus manecillas se han perdido, pero su propietario lo siguió conservando.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Exiliado","descripcion":"Una taza opaca hecha con metales pesados. Tuvo piedras preciosas incrustadas en su momento, pero alguien se las arrancó.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_1.png"},{"pieza":"Tiara de Logos","nombre":"Diadema del Exiliado","descripcion":"Una prestigiosa diadema. Su insignia real fue arañada con un objeto punzante y perdió su distinguida identidad original.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_3.png"}]'::jsonb, null),
  ('gi-artifact-10007', 'genshin-impact', 'Instructor', 'Instructor', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png', null, 'Maestría Elemental +80 pts.', 'Después de activar una Reacción Elemental, aumenta la Maestría Elemental de todos los miembros del equipo en 120 pts. durante 8 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Broche del Instructor","descripcion":"Cuando el Instructor llevaba puesto este broche, significaba que ese día no había entrenamiento.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Instructor","descripcion":"El Instructor, que dominaba el arte de desviar los ataques, sabía cómo mantener este accesorio a su alcance en todo momento.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo del Instructor","descripcion":"Un reloj de bolsillo que no muestra la hora actual, sino que cronometra las sesiones de entrenamiento.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Taza de Té del Instructor","descripcion":"Para la mayoría de personas, puede parecer una taza de té ordinaria, pero para los estudiantes, era el símbolo de la autoridad del Instructor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_1.png"},{"pieza":"Tiara de Logos","nombre":"Gorra del Instructor","descripcion":"El gorro que solía llevar el Instructor. Solo aquellos que rechazaron ser promocionados de rango podían obtener este honor.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_3.png"}]'::jsonb, null),
  ('gi-artifact-10008', 'genshin-impact', 'Jugadora', 'Gambler', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_4.png', null, 'Daño de Habilidad Elemental +20%.', 'Al derrotar a un enemigo, hay una probabilidad del 100% de reiniciar el TdE de la Habilidad Elemental. Puede ocurrir una vez cada 15 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Broche de la Jugadora","descripcion":"Una gran y hermosa flor que puede esconder un dado trucado.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de la Jugadora","descripcion":"La pluma de la cola de un pájaro muy grande que puede esconder una carta capaz de cambiar el destino.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo de la Jugadora","descripcion":"Un reloj de bolsillo roto que una vez bloqueó un golpe letal que se dirigía hacia su dueña.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cubilete de la Jugadora","descripcion":"Un cubilete que solo sirve para una cosa. No tiene compartimentos secretos incorporados en él.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_1.png"},{"pieza":"Tiara de Logos","nombre":"Aretes de la Jugadora","descripcion":"Un par de aretes azules que calman la mente y fomentan el pensamiento racional, muy útil para evaluar los riesgos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10008_3.png"}]'::jsonb, null),
  ('gi-artifact-10004', 'genshin-impact', 'Milagro', 'Tiny Miracle', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_4.png', null, '+20% en todas las RES Elementales.', 'El Daño Elemental recibido aumenta la RES Elemental correspondiente en un 30% durante 10 s. Solo puede ocurrir una vez cada 10 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Flor del Milagro","descripcion":"Una flor que creció de una roca. Fue capaz de atravesar la piedra, estremeciéndose para alcanzar la luz.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Milagro","descripcion":"Una pluma que pertenecía a un ave ágil y feroz. Era tan rápida que nunca fue avistada en pleno vuelo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Arena del Milagro","descripcion":"Parece ser un reloj de arena normal. Cuando se le da la vuelta, la arena seca que contiene se desliza tan rápido que parece agua fluyendo.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Milagro","descripcion":"Un vaso comúnmente usado para adivinar la suerte. También puede ser usado para contener agua, por supuesto.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_1.png"},{"pieza":"Tiara de Logos","nombre":"Aretes del Milagro","descripcion":"Un accesorio barato hecho con minerales de meteoritos antiguos.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10004_3.png"}]'::jsonb, null),
  ('gi-artifact-15009', 'genshin-impact', 'Ritual de la Iluminación', 'Prayers for Illumination', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png', 'Los efectos de Pyro causados sobre ti duran un 40% menos.', null, null, 'Jefes de mundo y enemigos élite (solo la tiara)', '[{"pieza":"Tiara de Logos","nombre":"Diadema Pírica","descripcion":"Una corona ceremonial portada por sacerdotes de tiempos antiguos al ofrecer un sacrificio a los dioses. Al haber estado expuesta a las llamas durante tanto tiempo, ha adquirido una resistencia asombrosa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png"}]'::jsonb, null),
  ('gi-artifact-15013', 'genshin-impact', 'Ritual de la Primavera', 'Prayers to Springtime', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png', 'Los efectos de Cryo causados sobre ti duran un 40% menos.', null, null, 'Jefes de mundo y enemigos élite (solo la tiara)', '[{"pieza":"Tiara de Logos","nombre":"Diadema de la Escarcha","descripcion":"Una corona ceremonial portada por sacerdotes de tiempos antiguos al ofrecer un sacrificio a los dioses. Su exposición constante al frío gélido le ha dado una resistencia asombrosa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png"}]'::jsonb, null),
  ('gi-artifact-15011', 'genshin-impact', 'Ritual de la Sabiduría', 'Prayers for Wisdom', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png', 'Los efectos de Electro causados sobre ti duran un 40% menos.', null, null, 'Jefes de mundo y enemigos élite (solo la tiara)', '[{"pieza":"Tiara de Logos","nombre":"Diadema del Trueno","descripcion":"Una corona ceremonial portada por sacerdotes de tiempos antiguos al ofrecer un sacrificio a los dioses. El escuchar constantemente el trueno le ha dado una resistencia asombrosa.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png"}]'::jsonb, null),
  ('gi-artifact-15010', 'genshin-impact', 'Ritual del Destino', 'Prayers for Destiny', 'artefacto', '3-4★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15010_3.png', 'Los efectos de Hydro causados sobre ti duran un 40% menos.', null, null, 'Jefes de mundo y enemigos élite (solo la tiara)', '[{"pieza":"Tiara de Logos","nombre":"Diadema Torrencial","descripcion":"Una corona ceremonial portada por sacerdotes de tiempos antiguos al ofrecer un sacrificio a los dioses. Haber estado sumergida bajo el agua durante tantos años le ha dado una increíble resistencia al agua.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15010_3.png"}]'::jsonb, null),
  ('gi-artifact-10011', 'genshin-impact', 'Afortunado', 'Lucky Dog', 'artefacto', '1-3★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_4.png', null, 'DEF +100.', 'Recoger Mora restaura 300 pts. de Vida.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Trébol de Cuatro Hojas del Afortunado","descripcion":"Un trébol de cuatro hojas que crece en la naturaleza. Fue arrancado porque se decía que traía suerte.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma de Águila del Afortunado","descripcion":"Un águila que cazaba detectó a un monstruo que había acorralado a un aventurero... El ave dejó caer esta pluma, que ahora lleva algo de la buena suerte de aquel aventurero.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Arena del Afortunado","descripcion":"Este reloj está desprovisto de arena debido al agujero que tiene. El paso del tiempo no tiene sentido para los que viven sin preocupaciones.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz del Afortunado","descripcion":"Un exquisito recipiente metálico que una vez fue usado para golpear a un ladrón.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_1.png"},{"pieza":"Tiara de Logos","nombre":"Tiara de Plata del Afortunado","descripcion":"Su antiguo dueño cayó una vez en una cueva y encontró el tesoro escondido de la realeza exiliada. Esto es un recuerdo de ese incidente.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_3.png"}]'::jsonb, null),
  ('gi-artifact-10010', 'genshin-impact', 'Aventurero', 'Adventurer', 'artefacto', '1-3★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_4.png', null, 'Vida Máx. +1000 pts.', 'Al abrir un cofre, se regenera un 30% de Vida durante 5 s.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Flor del Aventurero","descripcion":"Una flor resistente que sobrevivió al duro entorno de una antigua ciudad. Ahora se lleva con orgullo como una medalla.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Aventurero","descripcion":"La pluma de un ave exótica raramente vista en este continente.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo del Aventurero","descripcion":"Es fácil perder la noción del tiempo cuando te aventuras donde el sol no brilla, ya sea en las profundidades del abismo o en las ruinas de una ciudad perdida.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Cáliz Dorado del Aventurero","descripcion":"Trofeo de una de las batallas de algún aventurero. Aunque está un poco dañado, es de todas formas un hallazgo increíble.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_1.png"},{"pieza":"Tiara de Logos","nombre":"Bandana del Aventurero","descripcion":"Bandana que se ata en la frente. Aunque está impregnada de sudor y cubierta de polvo, la suciedad no puede esconder de ninguna forma el orgullo del Aventurero.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_3.png"}]'::jsonb, null),
  ('gi-artifact-10013', 'genshin-impact', 'Médica Itinerante', 'Traveling Doctor', 'artefacto', '1-3★', 'https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png', null, 'Curación recibida +20%.', 'Al lanzar una Habilidad Definitiva, restaura un 20% de Vida.', 'Cofres, enemigos élite y jefes de mundo', '[{"pieza":"Flor de la Vida","nombre":"Loto de Plata de la Médica Itinerante","descripcion":"Un precioso ingrediente medicinal que ha perdido todas sus propiedades curativas después de tanto tiempo sin ser usado.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png"},{"pieza":"Pluma de la Muerte","nombre":"Pluma del Búho de la Médica Itinerante","descripcion":"La pluma dura de un búho. Se utiliza como método de automotivación cuando se sale a tratar a los pacientes a altas horas de la noche.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_2.png"},{"pieza":"Arenas del Eón","nombre":"Reloj de Bolsillo de la Médica Itinerante","descripcion":"Una herramienta para saber la hora exacta. Para cualquier médico, cada segundo es muy importante.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_5.png"},{"pieza":"Cáliz de Eonothem","nombre":"Frasco de Medicinas de la Médica Itinerante","descripcion":"Solía llevar brebajes extremadamente potentes y refinados. El fuerte olor es todo lo que queda.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_1.png"},{"pieza":"Tiara de Logos","nombre":"Pañuelo de la Médica Itinerante","descripcion":"Se utiliza para atar el cabello mientras se trata a los pacientes, pero también se puede utilizar como vendaje para esguinces y fracturas de brazos en casos de emergencia.","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_3.png"}]'::jsonb, null)
on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      name_en = excluded.name_en,
      type = excluded.type,
      rarity = excluded.rarity,
      image_url = excluded.image_url,
      one_piece = excluded.one_piece,
      two_piece = excluded.two_piece,
      four_piece = excluded.four_piece,
      how_to_get = excluded.how_to_get,
      pieces = excluded.pieces,
      version = excluded.version,
      updated_at = now();

-- Comprobacion
select rarity, count(*) as conjuntos, count(how_to_get) as con_origen
from public.relic_sets
where game_id = 'genshin-impact'
group by rarity
order by rarity desc;
